<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('patients.view');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$id=(int)($_GET['id']??0);$st=db()->prepare("SELECT p.*,u.name professional_name FROM patients p JOIN users u ON u.id=p.primary_professional_id AND u.tenant_id=p.tenant_id WHERE p.id=:id AND p.tenant_id=:t");$st->execute(['id'=>$id,'t'=>$user['tenant_id']]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Paciente não encontrado.');}if(in_array($user['role_slug'],['psychologist','supervised'],true)&&!\App\Core\Rbac::canViewPatientClinical($user,$p)){http_response_code(403);require APP_ROOT.'/app/views/403.php';exit;}$canClinical=\App\Core\Rbac::allows((int)$user['id'],'clinical.view')&&\App\Core\Rbac::canViewPatientClinical($user,$p);$records=[];$tasks=[];$moods=[];if($canClinical){$st=db()->prepare("SELECT * FROM clinical_records WHERE tenant_id=:t AND patient_id=:p ORDER BY created_at DESC LIMIT 10");$st->execute(['t'=>$user['tenant_id'],'p'=>$id]);$records=$st->fetchAll();$st=db()->prepare("SELECT * FROM therapeutic_tasks WHERE tenant_id=:t AND patient_id=:p ORDER BY created_at DESC LIMIT 10");$st->execute(['t'=>$user['tenant_id'],'p'=>$id]);$tasks=$st->fetchAll();$st=db()->prepare("SELECT * FROM mood_logs WHERE tenant_id=:t AND patient_id=:p ORDER BY created_at DESC LIMIT 14");$st->execute(['t'=>$user['tenant_id'],'p'=>$id]);$moods=$st->fetchAll();audit('clinical.patient_view','patient',$id,[]);}layout('Paciente',function()use($p,$records,$tasks,$moods,$canClinical,$user){?>
<div class="page-head"><div><span class="eyebrow">Paciente <?=e($p['code'])?></span><h1 data-private><?=e($p['preferred_name']?:$p['name'])?></h1><p><?=e($p['approach']?:'Abordagem não informada')?> · Responsável: <?=e($p['professional_name'])?></p></div><div class="split-actions"><?php if($canClinical&&\App\Core\Rbac::allows((int)$user['id'],'clinical.write')):?><a class="button" href="<?=e(url('clinical/new.php?patient_id='.$p['id']))?>">+ Evolução</a><a class="button secondary" href="<?=e(url('patients/task.php?id='.$p['id']))?>">+ Tarefa</a><?php endif?></div></div>
<div class="grid-2"><section class="card"><h2>Cadastro</h2><div class="stack"><div><small class="muted">Nome completo</small><div data-private><?=e($p['name'])?></div></div><div class="form-row"><div><small class="muted">E-mail</small><div data-private><?=e($p['email']?:'—')?></div></div><div><small class="muted">Telefone</small><div data-private><?=e($p['phone']?:'—')?></div></div></div><div class="form-row"><div><small class="muted">CPF</small><div data-private><?=e($p['cpf']?:'—')?></div></div><div><small class="muted">Nascimento</small><div data-private><?=e($p['birth_date']?date('d/m/Y',strtotime($p['birth_date'])):'—')?></div></div></div></div><?php if(\App\Core\Rbac::allows((int)$user['id'],'patients.manage')):?><hr><a class="button ghost small" href="<?=e(url('patients/portal.php?id='.$p['id']))?>">Acesso ao portal</a><?php endif?></section>
<section class="card"><h2>Entre sessões</h2><?php if(!$canClinical):?><p class="muted">Seu perfil não possui acesso aos registros clínicos deste paciente.</p><?php else:?><div class="kpi-grid" style="grid-template-columns:1fr 1fr"><div class="kpi"><small>Tarefas abertas</small><strong><?=count(array_filter($tasks,fn($x)=>$x['status']==='open'))?></strong></div><div class="kpi"><small>Registros de humor</small><strong><?=count($moods)?></strong></div></div><?php if($moods):?><p class="muted">Último humor registrado: <strong><?=$moods[0]['mood_score']?>/10</strong> em <?=e(date('d/m H:i',strtotime($moods[0]['created_at'])))?>.</p><?php endif?><?php endif?></section></div>
<?php if($canClinical):?><section class="card" style="margin-top:18px"><h2>Linha do tempo clínica</h2><div class="timeline"><?php if(!$records):?><p class="muted">Ainda não há registros clínicos.</p><?php endif?><?php foreach($records as $r):$content=\App\Core\Crypto::decrypt($r['content_enc'],true);?><div class="timeline-item"><div class="timeline-date"><?=e(date('d/m/Y H:i',strtotime($r['created_at'])))?></div><div class="record"><div class="split-actions"><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span><span class="status"><?=e(strtoupper($r['record_type']))?></span></div><p data-private><?=e(mb_substr(is_array($content)?implode(' · ',array_filter(array_map('strval',$content))):(string)$content,0,360))?></p><a href="<?=e(url('clinical/view.php?id='.$r['id']))?>">Abrir registro</a></div></div><?php endforeach?></div></section><?php endif?>
<?php },['active'=>'patients']);
